package cl.bcs.oracle;

import java.lang.reflect.Type;
import java.sql.Connection;

import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import com.google.gson.JsonElement;
import com.google.gson.JsonNull;
import com.google.gson.JsonObject;

import cl.bcs.custodia.flujo.h2.FlujoGuion;

/**
 * Runtime of the REGISTERED DOUBLE of the ConsultarFlujoCustodia oracle (same role as BcsFondoMutuoServicios/legacy-oracle/runner/cl/bcs/oracle/Doubles.java).
 * The only double here is cl.bcs.custodia.utils.ValorizarInstrumento, generated by tools/gen_doubles.py --drop-helpers from the real source: its
 * {@code logica(Connection, ValorizarInstrumentoEntrada)} body calls {@link #answer}. The request object is serialised with the Gson below and handed
 * to the case script {@link FlujoGuion} (shared with the JUnit harness), which records it and returns the scripted ValorizarInstrumentoSalida JSON.
 * The shim cl.bcs.utils.Utils.getSecuencia (tools/gen_utils.py) reports every sequence request through {@link #registrarSecuencia}.
 *
 * <p>One fidelity rule: the {@code tipo} of every MensajeSalida of the scripted answer is INTERNED, because the real ValorizarInstrumento builds its
 * messages with the compile-time constants MensajeSalida.MENSAJE_ERROR / MENSAJE_ADVERTENCIA (ValorizarInstrumento.java:2397,2400) and the legacy
 * counter MensajeSalida.getNumeroErrores compares with {@code ==} (PlataformaUtils.java:636): a String built by Gson would never be counted.
 */
public final class Doubles {
    /** request serialisation (same settings as the FondoMutuo oracle Doubles OUT) */
    public static final Gson OUT = new GsonBuilder().serializeSpecialFloatingPointValues().setDateFormat("yyyy-MM-dd HH:mm:ss.SSS").serializeNulls()
            .disableHtmlEscaping().create();
    private static FlujoGuion guion = new FlujoGuion(null);

    private Doubles() {
    }

    public static void use(FlujoGuion g) {
        guion = g;
    }

    public static void registrarSecuencia(String nombre, long cantidad) {
        JsonObject o = new JsonObject();
        o.addProperty("secuencia", nombre);
        o.addProperty("cantidad", cantidad);
        guion.secuencias().add(o);
    }

    public static <T> T answer(String colab, String metodo, Object[] args, Class<T> ret) throws Exception {
        JsonElement req = JsonNull.INSTANCE;
        for (Object a : args) {
            if (a instanceof Connection) continue;
            req = OUT.toJsonTree(a);
            break;
        }
        JsonObject resp = guion.responder(colab, metodo, req);
        if (ret == Void.class || resp == null) return null;
        T v = cl.bcs.utils.Utils.getGsonBuilder().fromJson(resp, (Type) ret);
        internarTipos(v);
        return v;
    }

    private static void internarTipos(Object v) {
        if (v == null) return;
        try {
            java.lang.reflect.Field f = v.getClass().getField("P_OUT_MENSAJES");
            Object l = f.get(v);
            if (!(l instanceof java.util.List)) return;
            for (Object m : (java.util.List<?>) l) {
                if (m == null) continue;
                java.lang.reflect.Field t = m.getClass().getField("tipo");
                Object s = t.get(m);
                if (s instanceof String) t.set(m, ((String) s).intern());
            }
        } catch (NoSuchFieldException ex) {
            // not a Salida with messages
        } catch (IllegalAccessException ex) {
            throw new IllegalStateException(ex);
        }
    }
}
